CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS picks (player_id INTEGER NOT NULL, match_id TEXT NOT NULL, round INTEGER NOT NULL, hs INTEGER NOT NULL, aws INTEGER NOT NULL, updated TEXT NOT NULL, PRIMARY KEY (player_id, match_id));
CREATE TABLE IF NOT EXISTS leagues (code TEXT PRIMARY KEY, name TEXT NOT NULL, owner INTEGER NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (code TEXT NOT NULL, player_id INTEGER NOT NULL, PRIMARY KEY (code, player_id));
CREATE INDEX IF NOT EXISTS picks_round ON picks (round);
